print(a.execute('pragma user_version').fetchone(), b.execute('pragma user_version').fetchone())
sa={n:(t,s) for t,n,s in a.execute("select type,name,sql from sqlite_master")}; sb={n:(t,s) for t,n,s in b.execute("select type,name,sql from sqlite_master")}
print('added',set(sb)-set(sa),'removed',set(sa)-set(sb))
for n in sorted(set(sa)&set(sb)):
    if sa[n]!=sb[n]:
        print('CHANGED',sa[n][0],n)
        if sa[n][0]=='view':
            for l in difflib.unified_diff((sa[n][1] or '').splitlines(),(sb[n][1] or '').splitlines(),lineterm='',n=0):
                if not l.startswith(('---','+++','@@')): print('   ',l[:200])
