    q=f'select {",".join(chr(34)+c+chr(34) for c in cols)} from "{n}" order by 1,2'
    ra=a.execute(q).fetchall(); rb=b.execute(q).fetchall()
    if ra!=rb: bad+=1; print('ROWS DIFFER',n,len(ra),len(rb))
print('tables with differing rows:',bad)
print(b.execute("select count(*) from source_value_extractions where retired_at is not null or retired_by_session is not null or retirement_reason is not null").fetchone())
print(b.execute("select seq from sqlite_sequence where name='source_value_extractions'").fetchone())
for v in ['v_live_lens_links','v_scan_ledger','v_value_independence','v_unregistered_roots','v_root_id_conflicts','v_coverage_parameter_via_admission','v_reading_owed','v_deferred_acts','v_determination_provenance']:
    qa=a.execute(f'select * from {v} order by 1,2,3').fetchall(); qb=b.execute(f'select * from {v} order by 1,2,3').fetchall()
    print(v,len(qa),qa==qb)
print(b.execute("pragma integrity_check").fetchone(), b.execute("pragma foreign_key_check").fetchall()[:3])
